    final PutFlowFile putFlowFile1 = new PutFlowFile(tableName, row, columns1, null);
    final Collection<PutColumn> columns2 = Collections.singletonList(new PutColumn(columnFamily, columnQualifier, content2.getBytes(StandardCharsets.UTF_8)));
